+bool RichTextEdit::_parse_color_tag(const String &p_tag, Color &r_color) {
+	String color_text;
+	if (p_tag.begins_with("color=")) {
+		color_text = p_tag.substr(6).strip_edges().unquote();
+	} else if (p_tag.begins_with("color ")) {
+		Vector<String> parts = p_tag.split(" ", false, 1);
+		if (parts.size() == 2 && parts[1].strip_edges().begins_with("color=")) {
+			color_text = parts[1].strip_edges().substr(6).strip_edges().unquote();
+		}
+	}
+
+	if (color_text.is_empty()) {
+		return false;
+	}
+
+	Color invalid_color = Color(0, 0, 0, -1);
+	r_color = Color::from_string(color_text, invalid_color);
+	return r_color.a >= 0;
+}
+
+bool RichTextEdit::_parse_font_size_tag(const String &p_tag, int &r_size) {
+	String size_text;
+	if (p_tag.begins_with("font_size=")) {
+		size_text = p_tag.substr(10).strip_edges().unquote();
+	} else if (p_tag.begins_with("size=")) {
+		size_text = p_tag.substr(5).strip_edges().unquote();
+	}
+
+	if (size_text.is_empty() || !size_text.is_valid_int()) {
+		return false;
+	}
+
+	r_size = MAX(1, size_text.to_int());
+	return true;
+}
+
+bool RichTextEdit::_parse_url_tag(const String &p_tag, String &r_url) {
+	if (p_tag == "url") {
+		r_url = "";
+		return true;
+	}
+	if (p_tag.begins_with("url=")) {
+		r_url = p_tag.substr(4).strip_edges().unquote();
+		return true;
+	}
+	return false;
+}
