+RichTextEdit::TextStyle RichTextEdit::_get_style_at_offset(int p_offset) const {
+	for (const StyleSpan &span : style_spans) {
+		if (p_offset >= span.from && p_offset < span.to) {
+			return span.style;
+		}
+	}
+	return TextStyle();
+}
