+class RichTextEditHighlighter : public SyntaxHighlighter {
+	GDCLASS(RichTextEditHighlighter, SyntaxHighlighter);
+
+protected:
+	static void _bind_methods() {}
+
+public:
+	virtual Dictionary _get_line_syntax_highlighting_impl(int p_line) override {
+		Dictionary color_map;
+
+		RichTextEdit *rich_text_edit = Object::cast_to<RichTextEdit>(get_text_edit());
+		if (rich_text_edit == nullptr || p_line < 0 || p_line >= rich_text_edit->get_line_count()) {
+			return color_map;
+		}
+
+		const int line_start = rich_text_edit->_get_line_start_offset(p_line);
+		const int line_length = rich_text_edit->get_line(p_line).length();
+		const int line_end = line_start + line_length;
+
+		for (const RichTextEdit::StyleSpan &span : rich_text_edit->get_style_spans()) {
+			if (!span.style.has_color || span.to <= line_start || span.from >= line_end) {
+				continue;
+			}
+
+			const int from = MAX(span.from, line_start) - line_start;
+			const int to = MIN(span.to, line_end) - line_start;
+
+			Dictionary color_data;
+			color_data["color"] = span.style.color;
+			color_map[from] = color_data;
+			if (to < line_length) {
+				color_map[to] = Dictionary();
+			}
+		}
+
+		return color_map;
+	}
+};
+
+struct StyleSpanCompare {
+	_FORCE_INLINE_ bool operator()(const RichTextEdit::StyleSpan &p_a, const RichTextEdit::StyleSpan &p_b) const {
+		if (p_a.from == p_b.from) {
+			return p_a.to < p_b.to;
+		}
+		return p_a.from < p_b.from;
+	}
+};
+
+bool RichTextEdit::TextStyle::operator==(const TextStyle &p_other) const {
+	return bold == p_other.bold &&
+			italic == p_other.italic &&
+			underline == p_other.underline &&
+			strikethrough == p_other.strikethrough &&
+			has_color == p_other.has_color &&
+			(!has_color || color == p_other.color) &&
+			font_size == p_other.font_size &&
+			url == p_other.url;
+}
+
+bool RichTextEdit::TextStyle::is_default() const {
+	return !bold && !italic && !underline && !strikethrough && !has_color && font_size <= 0 && url.is_empty();
+}
+
+bool RichTextEdit::_is_supported_style_tag(const String &p_tag) {
+	return p_tag == "b" || p_tag == "i" || p_tag == "u" || p_tag == "s";
+}
+
+bool RichTextEdit::_parse_color_tag(const String &p_tag, Color &r_color) {
+	String color_text;
+	if (p_tag.begins_with("color=")) {
+		color_text = p_tag.substr(6).strip_edges().unquote();
+	} else if (p_tag.begins_with("color ")) {
+		Vector<String> parts = p_tag.split(" ", false, 1);
+		if (parts.size() == 2 && parts[1].strip_edges().begins_with("color=")) {
+			color_text = parts[1].strip_edges().substr(6).strip_edges().unquote();
+		}
+	}
+
+	if (color_text.is_empty()) {
+		return false;
+	}
+
+	Color invalid_color = Color(0, 0, 0, -1);
+	r_color = Color::from_string(color_text, invalid_color);
+	return r_color.a >= 0;
+}
+
+bool RichTextEdit::_parse_font_size_tag(const String &p_tag, int &r_size) {
+	String size_text;
+	if (p_tag.begins_with("font_size=")) {
+		size_text = p_tag.substr(10).strip_edges().unquote();
+	} else if (p_tag.begins_with("size=")) {
+		size_text = p_tag.substr(5).strip_edges().unquote();
+	}
+
+	if (size_text.is_empty() || !size_text.is_valid_int()) {
+		return false;
+	}
+
+	r_size = MAX(1, size_text.to_int());
+	return true;
+}
+
+bool RichTextEdit::_parse_url_tag(const String &p_tag, String &r_url) {
+	if (p_tag == "url") {
+		r_url = "";
+		return true;
+	}
+	if (p_tag.begins_with("url=")) {
+		r_url = p_tag.substr(4).strip_edges().unquote();
+		return true;
+	}
+	return false;
+}
+
+String RichTextEdit::_escape_bbcode_text(const String &p_text) {
+	return p_text.replace("[", "[lb]");
+}
+
+void RichTextEdit::_parse_bbcode(const String &p_bbcode, String &r_text, Vector<StyleSpan> &r_spans) const {
+	Vector<TextStyle> style_stack;
+	style_stack.push_back(TextStyle());
+
+	int pos = 0;
+	int text_pos = 0;
+	auto append_text = [&](const String &p_text) {
+		if (p_text.is_empty()) {
+			return;
+		}
+
+		const int from = text_pos;
+		r_text += p_text;
+		text_pos += p_text.length();
+
+		const TextStyle &style = style_stack[style_stack.size() - 1];
+		if (!style.is_default()) {
+			StyleSpan span;
+			span.from = from;
+			span.to = text_pos;
+			span.style = style;
+			r_spans.push_back(span);
+		}
+	};
+
+	while (pos < p_bbcode.length()) {
+		const int bracket_pos = p_bbcode.find_char('[', pos);
+		if (bracket_pos < 0) {
+			append_text(p_bbcode.substr(pos));
+			break;
+		}
+
+		if (bracket_pos > pos) {
+			append_text(p_bbcode.substr(pos, bracket_pos - pos));
+		}
+
+		const int close_pos = p_bbcode.find_char(']', bracket_pos + 1);
+		if (close_pos < 0) {
+			append_text(p_bbcode.substr(bracket_pos));
+			break;
+		}
+
+		String tag = p_bbcode.substr(bracket_pos + 1, close_pos - bracket_pos - 1).strip_edges();
+		String tag_lower = tag.to_lower();
+
+		if (tag_lower == "lb") {
+			append_text("[");
+			pos = close_pos + 1;
+			continue;
+		}
+
+		if (tag_lower.begins_with("/") && style_stack.size() > 1) {
+			String closing = tag_lower.substr(1);
+			if (_is_supported_style_tag(closing) || closing == "color" || closing == "font_size" || closing == "size" || closing == "url") {
+				style_stack.resize(style_stack.size() - 1);
+				pos = close_pos + 1;
+				continue;
+			}
+		}
+
+		TextStyle next_style = style_stack[style_stack.size() - 1];
+		Color parsed_color;
+		int parsed_size = 0;
+		String parsed_url;
+		if (tag_lower == "b") {
+			next_style.bold = true;
+			style_stack.push_back(next_style);
+			pos = close_pos + 1;
+			continue;
+		} else if (tag_lower == "i") {
+			next_style.italic = true;
+			style_stack.push_back(next_style);
+			pos = close_pos + 1;
+			continue;
+		} else if (tag_lower == "u") {
+			next_style.underline = true;
+			style_stack.push_back(next_style);
+			pos = close_pos + 1;
+			continue;
+		} else if (tag_lower == "s") {
+			next_style.strikethrough = true;
+			style_stack.push_back(next_style);
+			pos = close_pos + 1;
+			continue;
+		} else if (_parse_color_tag(tag_lower, parsed_color)) {
+			next_style.has_color = true;
+			next_style.color = parsed_color;
+			style_stack.push_back(next_style);
+			pos = close_pos + 1;
+			continue;
+		} else if (_parse_font_size_tag(tag_lower, parsed_size)) {
+			next_style.font_size = parsed_size;
+			style_stack.push_back(next_style);
+			pos = close_pos + 1;
+			continue;
+		} else if (_parse_url_tag(tag_lower, parsed_url)) {
+			next_style.url = parsed_url;
+			next_style.underline = true;
+			if (!next_style.has_color) {
+				next_style.has_color = true;
+				next_style.color = Color(0.25, 0.45, 1.0);
+			}
+			style_stack.push_back(next_style);
+			pos = close_pos + 1;
+			continue;
+		}
+
+		append_text(p_bbcode.substr(bracket_pos, close_pos - bracket_pos + 1));
+		pos = close_pos + 1;
+	}
+}
+
+void RichTextEdit::_sync_style_spans_for_text_change(const String &p_old_text, const String &p_new_text) {
+	int prefix = 0;
+	const int old_len = p_old_text.length();
+	const int new_len = p_new_text.length();
+	while (prefix < old_len && prefix < new_len && p_old_text[prefix] == p_new_text[prefix]) {
+		prefix++;
+	}
+
+	int suffix = 0;
+	while (suffix < old_len - prefix && suffix < new_len - prefix && p_old_text[old_len - suffix - 1] == p_new_text[new_len - suffix - 1]) {
+		suffix++;
+	}
+
+	const int old_from = prefix;
+	const int old_to = old_len - suffix;
+	const int new_to = new_len - suffix;
+	const int delta = (new_to - old_from) - (old_to - old_from);
+
+	Vector<StyleSpan> updated;
+	for (StyleSpan span : style_spans) {
+		if (span.to <= old_from) {
+			updated.push_back(span);
+		} else if (span.from >= old_to) {
+			span.from += delta;
+			span.to += delta;
+			updated.push_back(span);
+		} else {
+			if (span.from < old_from) {
+				StyleSpan left = span;
+				left.to = old_from;
+				updated.push_back(left);
+			}
+			if (span.to > old_to) {
+				StyleSpan right = span;
+				right.from = new_to;
+				right.to = span.to + delta;
+				updated.push_back(right);
+			}
+		}
+	}
+	style_spans = updated;
+
+	if (new_to > old_from) {
+		TextStyle insertion_style = typing_style_override ? typing_style : _get_insertion_style_at_offset(old_from);
+		if (!insertion_style.is_default()) {
+			_replace_style_range(old_from, new_to, insertion_style);
+		} else {
+			_merge_adjacent_spans();
+		}
+	} else {
+		_merge_adjacent_spans();
+	}
+	typing_style_override = false;
+}
+
+void RichTextEdit::_update_bbcode_from_text() {
+	if (setting_bbcode_text) {
+		return;
+	}
+
+	syncing_text_change = true;
+	String new_text = get_text();
+	_sync_style_spans_for_text_change(tracked_text, new_text);
+	tracked_text = new_text;
+	bbcode_text = get_bbcode_text();
+	syncing_text_change = false;
+
+	_refresh_style_rendering();
+}
+
+void RichTextEdit::_replace_style_range(int p_from, int p_to, const TextStyle &p_style) {
+	if (p_from > p_to) {
+		SWAP(p_from, p_to);
+	}
+	if (p_from == p_to) {
+		typing_style = p_style;
+		return;
+	}
+
+	const int text_len = get_text().length();
+	p_from = CLAMP(p_from, 0, text_len);
+	p_to = CLAMP(p_to, 0, text_len);
+
+	Vector<StyleSpan> updated;
+	for (StyleSpan span : style_spans) {
+		if (span.to <= p_from || span.from >= p_to) {
+			updated.push_back(span);
+			continue;
+		}
+		if (span.from < p_from) {
+			StyleSpan left = span;
+			left.to = p_from;
+			updated.push_back(left);
+		}
+		if (span.to > p_to) {
+			StyleSpan right = span;
+			right.from = p_to;
+			right.to = span.to;
+			updated.push_back(right);
+		}
+	}
+
+	if (!p_style.is_default()) {
+		StyleSpan replacement;
+		replacement.from = p_from;
+		replacement.to = p_to;
+		replacement.style = p_style;
+		updated.push_back(replacement);
+	}
+
+	style_spans = updated;
+	_merge_adjacent_spans();
+}
+
+void RichTextEdit::_apply_style_property_to_selection(StyleProperty p_property, const Variant &p_value, bool p_record_undo) {
+	int from = 0;
+	int to = 0;
+	const bool has_range = _get_selection_offsets(from, to);
+	if (!has_range) {
+		TextStyle style = typing_style;
+		switch (p_property) {
+			case STYLE_PROPERTY_BOLD:
+				style.bold = !style.bold;
+				break;
+			case STYLE_PROPERTY_ITALIC:
+				style.italic = !style.italic;
+				break;
+			case STYLE_PROPERTY_UNDERLINE:
+				style.underline = !style.underline;
+				break;
+			case STYLE_PROPERTY_STRIKETHROUGH:
+				style.strikethrough = !style.strikethrough;
+				break;
+			case STYLE_PROPERTY_COLOR:
+				style.has_color = true;
+				style.color = p_value;
+				break;
+			case STYLE_PROPERTY_CLEAR_COLOR:
+				style.has_color = false;
+				break;
+			case STYLE_PROPERTY_FONT_SIZE:
+				style.font_size = MAX(1, int(p_value));
+				break;
+			case STYLE_PROPERTY_CLEAR_FONT_SIZE:
+				style.font_size = 0;
+				break;
+			case STYLE_PROPERTY_URL:
+				style.url = p_value;
+				if (!style.url.is_empty()) {
+					style.underline = true;
+				}
+				break;
+			case STYLE_PROPERTY_CLEAR_URL:
+				style.url = "";
+				break;
+		}
+
+		typing_style = style;
+		typing_style_override = true;
+		bbcode_text = get_bbcode_text();
+		_refresh_style_rendering();
+		return;
+	}
+
+	const TextStyle first_selected_style = _get_selection_common_style();
+	Vector<int> boundaries;
+	boundaries.push_back(from);
+	boundaries.push_back(to);
+	for (const StyleSpan &span : style_spans) {
+		if (span.from > from && span.from < to) {
+			boundaries.push_back(span.from);
+		}
+		if (span.to > from && span.to < to) {
+			boundaries.push_back(span.to);
+		}
+	}
+	boundaries.sort();
+
+	Vector<StyleSpan> before_spans = style_spans;
+	TextStyle before_typing_style = typing_style;
+	const bool before_typing_style_override = typing_style_override;
+	for (int i = 0; i < boundaries.size() - 1; i++) {
+		const int segment_from = boundaries[i];
+		const int segment_to = boundaries[i + 1];
+		if (segment_from == segment_to) {
+			continue;
+		}
+
+		TextStyle style = _get_style_at_offset(segment_from);
+		switch (p_property) {
+			case STYLE_PROPERTY_BOLD:
+				style.bold = !first_selected_style.bold;
+				break;
+			case STYLE_PROPERTY_ITALIC:
+				style.italic = !first_selected_style.italic;
+				break;
+			case STYLE_PROPERTY_UNDERLINE:
+				style.underline = !first_selected_style.underline;
+				break;
+			case STYLE_PROPERTY_STRIKETHROUGH:
+				style.strikethrough = !first_selected_style.strikethrough;
+				break;
+			case STYLE_PROPERTY_COLOR:
+				style.has_color = true;
+				style.color = p_value;
+				break;
+			case STYLE_PROPERTY_CLEAR_COLOR:
+				style.has_color = false;
+				break;
+			case STYLE_PROPERTY_FONT_SIZE:
+				style.font_size = MAX(1, int(p_value));
+				break;
+			case STYLE_PROPERTY_CLEAR_FONT_SIZE:
+				style.font_size = 0;
+				break;
+			case STYLE_PROPERTY_URL:
+				style.url = p_value;
+				if (!style.url.is_empty()) {
+					style.underline = true;
+				}
+				break;
+			case STYLE_PROPERTY_CLEAR_URL:
+				style.url = "";
+				break;
+		}
+		_replace_style_range(segment_from, segment_to, style);
+	}
+
+	if (p_record_undo) {
+		_push_style_undo_snapshot(before_spans, before_typing_style, before_typing_style_override);
+	}
+	bbcode_text = get_bbcode_text();
+	_refresh_style_rendering();
+}
+
+RichTextEdit::TextStyle RichTextEdit::_get_insertion_style_at_offset(int p_offset) const {
+	const int caret_line = get_caret_line();
+	const int line_start = _get_line_start_offset(caret_line);
+	const int line_length = get_line(caret_line).length();
+	if (p_offset == line_start && line_length > 0) {
+		return _get_style_at_offset(line_start);
+	}
+	if (p_offset > line_start) {
+		return _get_style_at_offset(p_offset - 1);
+	}
+	return typing_style;
+}
+
+RichTextEdit::TextStyle RichTextEdit::_get_style_at_offset(int p_offset) const {
+	for (const StyleSpan &span : style_spans) {
+		if (p_offset >= span.from && p_offset < span.to) {
+			return span.style;
+		}
+	}
+	return TextStyle();
+}
+
+RichTextEdit::TextStyle RichTextEdit::_get_selection_common_style() const {
+	int from = 0;
+	int to = 0;
+	if (!_get_selection_offsets(from, to)) {
+		return typing_style;
+	}
+	return _get_style_at_offset(from);
+}
+
+int RichTextEdit::_get_default_font_size() const {
+	const int text_edit_font_size = get_theme_font_size(SNAME("font_size"));
+	if (text_edit_font_size > 0) {
+		return text_edit_font_size;
+	}
+
+	const int rich_text_label_font_size = get_theme_font_size(SNAME("normal_font_size"), SNAME("RichTextLabel"));
+	if (rich_text_label_font_size > 0) {
+		return rich_text_label_font_size;
+	}
+
+	return 16;
+}
+
+void RichTextEdit::_merge_adjacent_spans() {
+	style_spans.sort_custom<StyleSpanCompare>();
+	Vector<StyleSpan> merged;
+	for (const StyleSpan &span : style_spans) {
+		if (span.from >= span.to || span.style.is_default()) {
+			continue;
+		}
+		if (!merged.is_empty() && merged.write[merged.size() - 1].to == span.from && merged[merged.size() - 1].style == span.style) {
+			merged.write[merged.size() - 1].to = span.to;
+		} else {
+			merged.push_back(span);
+		}
+	}
+	style_spans = merged;
+}
+
+int RichTextEdit::_get_line_start_offset(int p_line) const {
+	int offset = 0;
+	for (int i = 0; i < p_line; i++) {
+		offset += get_line(i).length() + 1;
+	}
+	return offset;
+}
+
+int RichTextEdit::_get_caret_offset() const {
+	return _get_line_start_offset(get_caret_line()) + get_caret_column();
+}
+
+bool RichTextEdit::_get_selection_offsets(int &r_from, int &r_to) const {
+	if (!has_selection()) {
+		return false;
+	}
+	r_from = _get_line_start_offset(get_selection_from_line()) + get_selection_from_column();
+	r_to = _get_line_start_offset(get_selection_to_line()) + get_selection_to_column();
+	if (r_from > r_to) {
+		SWAP(r_from, r_to);
+	}
+	return r_from != r_to;
+}
+
+void RichTextEdit::_apply_style_to_selection(const TextStyle &p_style) {
+	Vector<StyleSpan> before_spans = style_spans;
+	TextStyle before_typing_style = typing_style;
+	const bool before_typing_style_override = typing_style_override;
+	int from = 0;
+	int to = 0;
+	const bool has_range = _get_selection_offsets(from, to);
+	if (has_range) {
+		_replace_style_range(from, to, p_style);
+	} else {
+		typing_style = p_style;
+		typing_style_override = true;
+	}
+
+	if (has_range) {
+		_push_style_undo_snapshot(before_spans, before_typing_style, before_typing_style_override);
+	}
+	bbcode_text = get_bbcode_text();
+	_refresh_style_rendering();
+}
+
+void RichTextEdit::_caret_style_context_changed() {
+	if (!syncing_text_change) {
+		typing_style_override = false;
+	}
+}
+
+Variant RichTextEdit::_make_style_state_variant(const Vector<StyleSpan> &p_spans, const TextStyle &p_typing_style, bool p_typing_style_override) const {
+	Dictionary state;
+	Array spans;
+	for (const StyleSpan &span : p_spans) {
+		Dictionary style;
+		style["bold"] = span.style.bold;
+		style["italic"] = span.style.italic;
+		style["underline"] = span.style.underline;
+		style["strikethrough"] = span.style.strikethrough;
+		style["has_color"] = span.style.has_color;
+		style["color"] = span.style.color;
+		style["font_size"] = span.style.font_size;
+		style["url"] = span.style.url;
+
+		Dictionary span_data;
+		span_data["from"] = span.from;
+		span_data["to"] = span.to;
+		span_data["style"] = style;
+		spans.push_back(span_data);
+	}
+
+	Dictionary typing_style_data;
+	typing_style_data["bold"] = p_typing_style.bold;
+	typing_style_data["italic"] = p_typing_style.italic;
+	typing_style_data["underline"] = p_typing_style.underline;
+	typing_style_data["strikethrough"] = p_typing_style.strikethrough;
+	typing_style_data["has_color"] = p_typing_style.has_color;
+	typing_style_data["color"] = p_typing_style.color;
+	typing_style_data["font_size"] = p_typing_style.font_size;
+	typing_style_data["url"] = p_typing_style.url;
+
+	state["spans"] = spans;
+	state["typing_style"] = typing_style_data;
+	state["typing_style_override"] = p_typing_style_override;
+	return state;
+}
+
+void RichTextEdit::_restore_style_state_variant(const Variant &p_state) {
+	Dictionary state = p_state;
+	Array spans = state.get("spans", Array());
+
+	Vector<StyleSpan> restored_spans;
+	for (int i = 0; i < spans.size(); i++) {
+		Dictionary span_data = spans[i];
+		Dictionary style_data = span_data.get("style", Dictionary());
+
+		StyleSpan span;
+		span.from = span_data.get("from", 0);
+		span.to = span_data.get("to", 0);
+		span.style.bold = style_data.get("bold", false);
+		span.style.italic = style_data.get("italic", false);
+		span.style.underline = style_data.get("underline", false);
+		span.style.strikethrough = style_data.get("strikethrough", false);
+		span.style.has_color = style_data.get("has_color", false);
+		span.style.color = style_data.get("color", Color());
+		span.style.font_size = style_data.get("font_size", 0);
+		span.style.url = style_data.get("url", String());
+		restored_spans.push_back(span);
+	}
+
+	Dictionary typing_style_data = state.get("typing_style", Dictionary());
+	TextStyle restored_typing_style;
+	restored_typing_style.bold = typing_style_data.get("bold", false);
+	restored_typing_style.italic = typing_style_data.get("italic", false);
+	restored_typing_style.underline = typing_style_data.get("underline", false);
+	restored_typing_style.strikethrough = typing_style_data.get("strikethrough", false);
+	restored_typing_style.has_color = typing_style_data.get("has_color", false);
+	restored_typing_style.color = typing_style_data.get("color", Color());
+	restored_typing_style.font_size = typing_style_data.get("font_size", 0);
+	restored_typing_style.url = typing_style_data.get("url", String());
+
+	style_spans = restored_spans;
+	typing_style = restored_typing_style;
+	typing_style_override = state.get("typing_style_override", false);
+	_merge_adjacent_spans();
+	bbcode_text = get_bbcode_text();
+	_refresh_style_rendering();
+}
+
+void RichTextEdit::_push_style_undo_snapshot(const Vector<StyleSpan> &p_before_spans, const TextStyle &p_before_typing_style, bool p_before_typing_style_override) {
+	if (p_before_spans == style_spans && p_before_typing_style == typing_style && p_before_typing_style_override == typing_style_override) {
+		return;
+	}
+
+	push_custom_undo_operation(SNAME("rich_text_edit_style"), _make_style_state_variant(p_before_spans, p_before_typing_style, p_before_typing_style_override), _make_style_state_variant(style_spans, typing_style, typing_style_override));
+}
+
+void RichTextEdit::_refresh_style_rendering() {
+	set_style_parser(Callable());
+	set_style_parser(callable_mp(this, &RichTextEdit::_get_line_style_spans));
+	if (bbcode_highlighter.is_valid()) {
+		bbcode_highlighter->clear_highlighting_cache();
+
+		// TextEdit keeps its own converted syntax color cache. Reassign the
+		// highlighter to force that cache to rebuild even when text did not edit.
+		set_syntax_highlighter(Ref<SyntaxHighlighter>());
+		set_syntax_highlighter(bbcode_highlighter);
+	}
+	queue_redraw();
+}
+
+Array RichTextEdit::_get_line_style_spans(int p_line) const {
+	Array result;
+	const int line_start = _get_line_start_offset(p_line);
+	const int line_length = get_line(p_line).length();
+	const int line_end = line_start + line_length;
+	for (const StyleSpan &span : style_spans) {
+		if (span.to <= line_start || span.from >= line_end) {
+			continue;
+		}
+		if (!span.style.bold && !span.style.italic && span.style.font_size <= 0) {
+			continue;
+		}
+
+		Ref<Font> font;
+		int font_size = span.style.font_size;
+		if (span.style.bold && span.style.italic) {
+			font = get_theme_font(SNAME("bold_italics_font"), SNAME("RichTextLabel"));
+		} else if (span.style.bold) {
+			font = get_theme_font(SNAME("bold_font"), SNAME("RichTextLabel"));
+		} else if (span.style.italic) {
+			font = get_theme_font(SNAME("italics_font"), SNAME("RichTextLabel"));
+		}
+
+		Dictionary info;
+		info["from"] = MAX(span.from, line_start) - line_start;
+		info["to"] = MIN(span.to, line_end) - line_start;
+		if (font.is_valid()) {
+			info["font"] = font;
+		}
+		if (font_size > 0) {
+			info["font_size"] = font_size;
+		}
+		result.push_back(info);
+	}
+	return result;
+}
+
+void RichTextEdit::_draw_decoration_lines() {
+	for (const StyleSpan &span : style_spans) {
+		if (!span.style.underline && !span.style.strikethrough && span.style.url.is_empty()) {
+			continue;
+		}
+
+		Color color = span.style.has_color ? span.style.color : Color(1, 1, 1);
+		for (int line = 0; line < get_line_count(); line++) {
+			const int line_start = _get_line_start_offset(line);
+			const int line_end = line_start + get_line(line).length();
+			if (span.to <= line_start || span.from >= line_end) {
+				continue;
+			}
+
+			const int from_col = MAX(span.from, line_start) - line_start;
+			const int to_col = MIN(span.to, line_end) - line_start;
+			Rect2i from_rect = get_rect_at_line_column(line, from_col);
+			Rect2i to_rect = get_rect_at_line_column(line, to_col);
+			float y = from_rect.position.y + from_rect.size.y - 3;
+			if (span.style.strikethrough) {
+				y = from_rect.position.y + from_rect.size.y * 0.55;
+			}
+			draw_line(Point2(from_rect.position.x, y), Point2(to_rect.position.x, y), color, 1.0);
+		}
+	}
+}
+
+void RichTextEdit::_notification(int p_what) {
+	if (p_what == NOTIFICATION_DRAW) {
+		_draw_decoration_lines();
+	}
+}
