+
+String RichTextEdit::get_bbcode_text() const {
+	String plain_text = get_text();
+	String bbcode;
+	int cursor = 0;
+	for (const StyleSpan &span : style_spans) {
+		if (span.from > cursor) {
+			bbcode += _escape_bbcode_text(plain_text.substr(cursor, span.from - cursor));
+		}
+		if (span.style.bold) {
+			bbcode += "[b]";
+		}
+		if (span.style.italic) {
+			bbcode += "[i]";
+		}
+		if (span.style.underline) {
+			bbcode += "[u]";
+		}
+		if (span.style.strikethrough) {
+			bbcode += "[s]";
+		}
+		if (span.style.has_color) {
+			bbcode += "[color=" + span.style.color.to_html(span.style.color.a < 1.0) + "]";
+		}
+		if (span.style.font_size > 0) {
+			bbcode += "[font_size=" + itos(span.style.font_size) + "]";
+		}
+		if (!span.style.url.is_empty()) {
+			bbcode += "[url=" + span.style.url + "]";
+		}
+
+		bbcode += _escape_bbcode_text(plain_text.substr(span.from, span.to - span.from));
+
+		if (!span.style.url.is_empty()) {
+			bbcode += "[/url]";
+		}
+		if (span.style.font_size > 0) {
+			bbcode += "[/font_size]";
+		}
+		if (span.style.has_color) {
+			bbcode += "[/color]";
+		}
+		if (span.style.strikethrough) {
+			bbcode += "[/s]";
+		}
+		if (span.style.underline) {
+			bbcode += "[/u]";
+		}
+		if (span.style.italic) {
+			bbcode += "[/i]";
+		}
+		if (span.style.bold) {
+			bbcode += "[/b]";
+		}
+		cursor = span.to;
+	}
+	if (cursor < plain_text.length()) {
+		bbcode += _escape_bbcode_text(plain_text.substr(cursor));
+	}
+	return bbcode;
+}
