+int RichTextEdit::get_current_font_size() const {
+	int offset = 0;
+	if (has_selection()) {
+		int to = 0;
+		_get_selection_offsets(offset, to);
+	} else {
+		const int caret_line = get_caret_line();
+		const int caret_column = get_caret_column();
+		const int line_start = _get_line_start_offset(caret_line);
+		if (caret_column == 0) {
+			offset = get_line(caret_line).is_empty() ? line_start : line_start;
+		} else {
+			offset = line_start + caret_column - 1;
+		}
+	}
+
+	const TextStyle style = _get_style_at_offset(offset);
+	return style.font_size > 0 ? style.font_size : _get_default_font_size();
+}
+
+void RichTextEdit::increase_indent() {
+	int from_line = has_selection() ? get_selection_from_line() : get_caret_line();
+	int to_line = has_selection() ? get_selection_to_line() : get_caret_line();
+	bool had_selection = has_selection();
+	int selection_from_column = had_selection ? get_selection_from_column() : 0;
+	int selection_to_column = had_selection ? get_selection_to_column() : 0;
+	int caret_line = get_caret_line();
+	int caret_column = get_caret_column();
+	for (int line = from_line; line <= to_line; line++) {
+		set_line(line, "\t" + get_line(line));
+	}
+	if (had_selection) {
+		select(from_line, selection_from_column + 1, to_line, selection_to_column + 1);
+	} else {
+		set_caret_line(caret_line);
+		set_caret_column(caret_column + 1);
+	}
+}
+
+void RichTextEdit::decrease_indent() {
+	int from_line = has_selection() ? get_selection_from_line() : get_caret_line();
+	int to_line = has_selection() ? get_selection_to_line() : get_caret_line();
+	bool had_selection = has_selection();
+	int selection_from_column = had_selection ? get_selection_from_column() : 0;
+	int selection_to_column = had_selection ? get_selection_to_column() : 0;
+	int caret_line = get_caret_line();
+	int caret_column = get_caret_column();
+	int from_delta = 0;
+	int to_delta = 0;
+	int caret_delta = 0;
+	for (int line = from_line; line <= to_line; line++) {
+		String line_text = get_line(line);
+		int removed = 0;
+		if (line_text.begins_with("\t")) {
+			set_line(line, line_text.substr(1));
+			removed = 1;
+		} else if (line_text.begins_with("    ")) {
+			set_line(line, line_text.substr(4));
+			removed = 4;
+		}
+		if (line == from_line) {
+			from_delta = removed;
+		}
+		if (line == to_line) {
+			to_delta = removed;
+		}
+		if (line == caret_line) {
+			caret_delta = removed;
+		}
+	}
+	if (had_selection) {
+		select(from_line, MAX(0, selection_from_column - from_delta), to_line, MAX(0, selection_to_column - to_delta));
+	} else {
+		set_caret_line(caret_line);
+		set_caret_column(MAX(0, caret_column - caret_delta));
+	}
+}
