+	for (int i = p_from; i < p_src.length(); i++) {
+		const char32_t c = p_src[i];
+		if (in_double_quote) {
+			if (c == '"') {
+				in_double_quote = false;
+			}
+		} else if (in_single_quote) {
+			if (c == '\'') {
+				in_single_quote = false;
+			}
+		} else if (c == '"') {
+			in_double_quote = true;
+		} else if (c == '\'') {
