+Variant RichTextEdit::_make_style_state_variant(const Vector<StyleSpan> &p_spans, const Vector<RichTextDocument::Image> &p_images, const Vector<RichTextDocument::RawInline> &p_raw_inlines, const TextStyle &p_typing_style, bool p_typing_style_override) const {
